import 'package:family_veda/models/health_record.dart';
import 'package:family_veda/models/record_summary_meta.dart';
import 'package:flutter_test/flutter_test.dart';

void main() {
  test('round-trips status, severity, doctor and free text', () {
    const meta = RecordSummaryMeta(
      status: 'Active',
      severity: 'Moderate',
      doctor: 'Dr. Perera',
      cleanSummary: 'Synthetic note.',
    );
    final summary = meta.format();

    expect(summary, 'Status: Active · Severity: Moderate · Doctor: Dr. Perera\nSynthetic note.');
    final parsed = RecordSummaryMeta.parse(summary);
    expect(parsed.status, 'Active');
    expect(parsed.severity, 'Moderate');
    expect(parsed.doctor, 'Dr. Perera');
    expect(parsed.cleanSummary, 'Synthetic note.');
  });

  test('writes no metadata line when nothing is chosen', () {
    expect(const RecordSummaryMeta(cleanSummary: 'Only text').format(), 'Only text');
    expect(const RecordSummaryMeta().format(), '');
  });

  test('does not invent metadata for plain or label-mentioning text', () {
    final parsed = RecordSummaryMeta.parse('Seen at clinic. Doctor: said to rest');
    expect(parsed.metaLine, '');
    expect(parsed.cleanSummary, 'Seen at clinic. Doctor: said to rest');
    expect(RecordSummaryMeta.parse(null).status, '');
  });

  test('HealthRecord keeps the summary returned by the API', () {
    final record = HealthRecord.fromJson({
      'id': 'r-1',
      'memberId': 'm-1',
      'recordType': 'Condition',
      'title': 'Synthetic condition',
      'occurredOn': '2026-10-02',
      'summary': 'Status: Resolved',
    });
    expect(RecordSummaryMeta.parse(record.summary).status, 'Resolved');
  });
}
